    {
      "path": "src/decompress-shared.ts",
      "content": "import {\n    blockDocs,\n    collectBlockContent,\n    markBlockRestoredInline,\n    matchToolMessagePattern,\n    parseBoundary,\n    retrieveByRef,\n    retrievedMessageId,\n    searchBlocks,\n    toolPathOf,\n    type CompressionBlock,\n    type CompressionCore,\n    type CompressionState,\n    type Config,\n    type CoreMessage,\n    type InlineRestoreResult,\n    type SearchDoc,\n    type SearchResult,\n} from \"acp-kernel\";\nimport { existsSync, mkdirSync, unlinkSync, writeFileSync } from \"node:fs\";\nimport { dirname, join, resolve as resolvePath } from \"node:path\";\nimport { tmpdir } from \"node:os\";\nimport { fileURLToPath } from \"node:url\";\nimport { markDirty, preCompactionArchiveOf, peekSession, findSessionByCanonicalId, type Session } from \"./session.js\";\nimport { getStore } from \"./persist.js\";\nimport { ccrEnabled, contentStoreOf } from \"./store.js\";\nimport { safePrefix } from \"./text-safe.js\";\nimport { decompressTmpCap as knobDecompressTmpCap } from \"./knobs.js\";\nimport { toolFail, toolOk, type ProxyToolResult } from \"./proxy-tool-result.js\";\nimport { describeRestorable } from \"./image-restore.js\";\n\n/** Bounded retention for large-decompress temp files. Each decompress with\n *  body > 10000 writes one file under tmpdir(); the reaper unlinks oldest past\n *  BILI_DECOMPRESS_TMP_CAP (default 50) and beforeExit cleans all. */\ntype TrackedTempFile = { path: string; mtimeMs: number };\nconst trackedTempFiles: TrackedTempFile[] = [];\n\nfunction getDecompressTmpCap(): number {\n    return knobDecompressTmpCap();\n}\n\nfunction reapTempFiles(): void {\n    const cap = getDecompressTmpCap();\n    while (trackedTempFiles.length > cap) {\n        trackedTempFiles.sort((a, b) => a.mtimeMs - b.mtimeMs);\n        const oldest = trackedTempFiles.shift();\n        if (!oldest) break;\n        try {\n            unlinkSync(oldest.path);\n        } catch {}\n    }\n}\n\nprocess.on(\"beforeExit\", () => {\n    for (const f of trackedTempFiles) {\n        try {\n            unlinkSync(f.path);\n        } catch {}\n    }\n    trackedTempFiles.length = 0;\n});\n\n/** Shared ctx shape used by both the chat and responses compress loops. */\nexport type ProxyToolCtx = {\n    core: CompressionCore;\n    config: Config;\n    messages: CoreMessage[];\n    /** Unfolded original history. Loop paths hand the folded view as\n     *  `messages`; decompress's cache-miss fallback must scan this instead. */\n    compressMessages?: CoreMessage[];\n    session: Session;\n    log: (msg: string) => void;\n};\n\n/** #2204: classify a toFile target BEFORE touching the filesystem. Plain paths\n *  (POSIX, Windows drive letters `C:\\x`/`c:/x`, UNC) go through path.resolve as\n *  before. A `scheme://` form whose scheme has ≥2 characters is a URI, not a\n *  path — single-letter \"schemes\" are drive letters, never URIs (`C://x` stays\n *  a path): `file://` resolves via fileURLToPath, every other scheme (host\n *  virtual files, e.g. OMP's `local://`) is refused up front. bili has no\n *  resolver for it and must not mkdir a directory named after its scheme. */\nfunction resolveToFileTarget(target: string): { resolved?: string; refusal?: string } {\n    const uri = target.match(/^([a-zA-Z][a-zA-Z0-9+.\\-]*):\\/\\//);\n    if (uri && uri[1]!.length >= 2) {\n        const scheme = uri[1]!.toLowerCase();\n        if (scheme === \"file\") {\n            try {\n                return { resolved: fileURLToPath(new URL(target)) };\n            } catch (e) {\n                return { refusal: `malformed file:// URI \"${target}\" (${String(e)})` };\n            }\n        }\n        return { refusal: `unsupported virtual URI scheme \"${scheme}\" in toFile \"${target}\" — bili writes to the local filesystem only; pass an actual filesystem path (absolute, or relative to the proxy cwd) or a file:// URI` };\n    }\n    return { resolved: resolvePath(target) };\n}\n\n/** #2204: shared failure receipt for export paths. Starts with \"[decompress\n *  FAILED:\" so the wire loop's repeat-failure guard (loop/core.ts) and the\n *  plugin-mode success-header detection (plugin.ts) both read it as a failure;\n *  labels the preview as NOT a completed export, keeps the OS reason, and gives\n *  a recoverable retry. */\nfunction exportFailureReceipt(path: string, err: unknown, body: string): ProxyToolResult {\n    const preview = safePrefix(body, 4000);\n    const scope = preview.length < body.length ? `partial content follows (${preview.length} of ${body.length} chars)` : \"full content follows\";\n    return toolFail(\n        `[decompress FAILED: could not write export to ${path}: ${String(err)}]\\n` +\n        `The export did NOT complete — ${scope}. Retry with a writable filesystem path, or omit toFile to restore inline.\\n` +\n        preview,\n    );\n}\n\n/** #1691: honor the documented `toFile` argument. A non-empty string writes the\n *  restore to the caller's path regardless of body size (never inflates context;\n *  relative paths resolve against the proxy cwd). An explicit destination is an\n *  intentional artifact, so it is deliberately NOT pushed into trackedTempFiles —\n *  the reaper/beforeExit cleanup must never remove a file asked for by name.\n *  Returns null when toFile was omitted so the caller uses its default; otherwise\n *  a status-carrying result (#2204) — success pointer on write, toolFail receipt\n *  when the target is refused or the write fails. Never a bare string, so no\n *  caller can re-wrap a failure as toolOk. */\nfunction toFilePointer(args: Record<string, unknown>, ctx: ProxyToolCtx, header: string, body: string): ProxyToolResult | null {\n    const raw = args.toFile;\n    if (raw === undefined || raw === null) return null;\n    if (typeof raw !== \"string\") {\n        ctx.log(`[acp-decompress] toFile must be a string (got ${typeof raw}) — using default output`);\n        return null;\n    }\n    const target = raw.trim();\n    if (target === \"\") return null;\n    const t = resolveToFileTarget(target);\n    if (t.refusal !== undefined) {\n        ctx.log(`[acp-decompress] toFile refused before any file operation: ${t.refusal}`);\n        return toolFail(`[decompress FAILED: ${t.refusal}]`);\n    }\n    const resolved = t.resolved!;\n    try {\n        mkdirSync(dirname(resolved), { recursive: true });\n        writeFileSync(resolved, body, { encoding: \"utf8\", mode: 0o600 });\n        return toolOk(`${header}\\nContent (${body.length} chars) written to: ${resolved}\\nUse the read tool to access it.`);\n    } catch (e) {\n        ctx.log(`[acp-decompress] toFile write failed: ${resolved} — ${String(e)}`);\n        return exportFailureReceipt(resolved, e, body);\n    }\n}\n\n/** Resolve a decompress request to a result string, honoring the `full` flag\n *  and the cross-round original-content cache on the session.\n *\n *  STATELESS RETRIEVAL: decompress is copy-paste — the block stays active, the\n *  forwarded view keeps folding, the cache is kept (repeat decompresses are\n *  free), and there is no expand/re-fold cycle. The one exception is the\n *  inline whole-block path, which additionally flags the block restoredInline\n *  so a later compress may refold it in place (#1294 P2 / kernel K2) — a\n *  sidecar flag only; ids and refs never move.\n *\n *  - If the block has cached originals (captured at compress time), use the\n *    cached `one` or `full` view per the flag. This is the cross-round-safe\n *    path: ctx.messages only holds the folded view by the time decompress runs.\n *  - Otherwise fall back to collectBlockContent against the unfolded view\n *    (ctx.compressMessages ?? ctx.messages); if that yields nothing, return\n *    the block summary. */\n/** A decompress call asks for a range restore only when at least one range\n *  field carries a non-blank value (#1712). */\nfunction hasRangeArgs(args: Record<string, unknown>): boolean {\n    const start = typeof args.startId === \"string\" ? args.startId.trim() : \"\";\n    const end = typeof args.endId === \"string\" ? args.endId.trim() : \"\";\n    return start !== \"\" || end !== \"\";\n}\n\nexport function resolveDecompress(\n    args: Record<string, unknown>,\n    ctx: ProxyToolCtx,\n): ProxyToolResult {\n    // #1995: image recovery is a distinct mode selected by a VALID imageRef — a\n    // non-blank string (mNNNNN ref or \"list\"), independent of blockId/range,\n    // intercepted first so an image-ref call never trips the blockId gate below.\n    // #2626: key on a NON-BLANK VALUE, not field presence — hosts/models emit\n    // \"\"/whitespace/null for optional fields, and presence-based dispatch hijacked\n    // the text path (valid blockId + imageRef:\"\" returned the image-list receipt\n    // instead of restoring the block). Blank/null/undefined ⇒ unspecified → fall\n    // through to block/range restore; a non-string non-null value is a loud param\n    // error, not a silent default to the image list.\n    const ir = args.imageRef;\n    if (ir != null && typeof ir !== \"string\") {\n        return toolFail('[decompress FAILED: imageRef must be a string (an mNNNNN ref or \"list\") — omit it to restore a text block]');\n    }\n    if (typeof ir === \"string\" && ir.trim() !== \"\") {\n        return resolveImageRestore(args, ctx);\n    }\n    const rawBlockId = args.blockId;\n    if (typeof rawBlockId !== \"string\" || rawBlockId.length === 0) {\n        return toolFail(\"[decompress FAILED: blockId is required]\");\n    }\n    const blockId = rawBlockId.trim();\n    const block = ctx.core.decompress(blockId, ctx.session.state);\n    if (!block) {\n        // Removed-from-state blocks (the #2695 reap path, or a future archive\n        // that drops blocks) still carry their preCompactionArchive entry: fail\n        // with the real reason instead of the misleading \"not found\" — the\n        // model got here by citing a ref from a summary it legitimately saw.\n        const selfArchived = preCompactionArchiveOf(ctx.session)[blockId];\n        if (selfArchived !== undefined) {\n            return toolFail(`[decompress FAILED: block ${blockId} is an archived block (${selfArchived.reason}) — it was removed from live state along with its covered substrate and cannot be restored.]`);\n        }\n        return resolveDerivedDecompress(args, ctx, blockId);\n    }\n    const archived = preCompactionArchiveOf(ctx.session);\n    if (archived[blockId] !== undefined) {\n        return toolFail(`[decompress FAILED: block ${blockId} is a pre-compaction archive — its content was in the history BEFORE the client's native compaction and is no longer reachable (replaced by the client's compaction summary). decompress is unavailable for archived blocks.]`);\n    }\n    // #1712: blank/whitespace range fields mean \"unspecified\" — hosts and models\n    // emit \"\" for optional fields, and treating that as a range request produced\n    // an unsatisfiable retry loop (fill in a real range → refused in plugin mode).\n    if (hasRangeArgs(args)) {\n        return resolveDecompressRange(args, ctx, block);\n    }\n\n    const full = args.full === true || args.full === \"true\";\n    const cached = ctx.session.blockContents.get(blockId);\n    let body: string;\n    let count: number;\n    if (cached) {\n        // Honor the full flag: `one` = direct msgs + nested child summaries,\n        // `full` = all original messages. Returning the cached full text\n        // unconditionally would break the default one-level semantics.\n        // `one === null` means the two views were byte-identical at cache\n        // time and deduped to one copy (#401).\n        const view = full ? cached.full : (cached.one ?? cached.full);\n        body = view.text;\n        count = view.count;\n    } else {\n        const collected = collectBlockContent(ctx.session.state, block, ctx.compressMessages ?? ctx.messages, { full });\n        body = collected.text || block.summary;\n        count = collected.count;\n    }\n    // #1336: retrieve-quality proxy — a whole-block restore where a precise\n    // path existed (per-message coverage recorded AND CCR armed ⇒ range-restore\n    // or targeted acp_retrieve would have sufficed) is the failure shape plan-\n    // aware search steering exists to prevent.\n    ctx.session.stats.wholeBlockRestores = (ctx.session.stats.wholeBlockRestores ?? 0) + 1;\n    if (coveredRefSpan(ctx.session.state, block) !== null && ccrEnabled(ctx.session)) {\n        ctx.session.stats.wholeBlockRestoresPreciseAvailable = (ctx.session.stats.wholeBlockRestoresPreciseAvailable ?? 0) + 1;\n    }\n\n    const header = `[Block ${blockId} content — ${count} item(s)${full ? \", full\" : \"\"}]`;\n    const toFileOut = toFilePointer(args, ctx, header, body);\n    if (toFileOut !== null) return toFileOut;\n    const safeBlockId = blockId.replace(/[^a-zA-Z0-9_-]/g, \"-\");\n    const outPath = body.length > 10000 ? join(tmpdir(), `acp-decompress-${safeBlockId}-${Date.now()}.txt`) : null;\n    if (outPath) {\n        try {\n            mkdirSync(dirname(outPath), { recursive: true });\n            writeFileSync(outPath, body, { encoding: \"utf8\", mode: 0o600 });\n            trackedTempFiles.push({ path: outPath, mtimeMs: Date.now() });\n            reapTempFiles();\n            return toolOk(`${header}\\nContent (${body.length} chars) written to: ${outPath}\\nUse the read tool to access it.`);\n        } catch (e) {\n            return exportFailureReceipt(outPath, e, body);\n        }\n    }\n    // #398/#403 + #1294 P2 wiring (dedup of #1316 × #1298): a successful INLINE\n    // whole-block restore hands the block's re-summarization material back to\n    // the model via this tool result, and the client keeps tool results in its\n    // re-sent history — flag restoredInline so a later compress refolds the\n    // block in place (kernel K2) instead of bouncing off \"already\n    // compressed\". The toFile path above returns BEFORE this point and stays\n    // byte-identical to pre-refold behavior (no flag, no hint — the material\n    // lives in a temp file, not the conversation). Range restores\n    // (startId/endId) return partial content and never reach here; inactive\n    // blocks can never refold.\n    if (!block.active) return toolOk(`${header}\\n${body}`);\n    // The kernel result is idempotent — a repeat restore recomputes the same\n    // span, so the hint stays byte-identical across repeats (old contract:\n    // repeat decompress returns identical content). Only the FIRST restore\n    // pays the state write + persist.\n    const marked = markBlockRestoredInline(ctx.session.state, blockId);\n    if (block.restoredInline !== true) {\n        ctx.session.state = marked.state;\n        markDirty(ctx.session);\n        ctx.log(`[acp-decompress-inline] ${blockId}: flagged restoredInline${marked.result?.restoredStartRef ? ` (${marked.result.restoredStartRef}–${marked.result.restoredEndRef})` : \"\"}`);\n    }\n    return toolOk(`${header}\\n${body}\\n\\n${refoldHint(blockId, marked.result)}`);\n}\n\n// #1995: restore the original pixels of a stripped/folded image by ref. Delivery\n// is file-first — images are spilled under <stateDir>/retrieve/img/ at index time\n// and their paths returned for the model to open with its read tool — uniform\n// across all four wires (no per-protocol inline-image rendering). \"list\" enumerates\n// what is currently restorable instead of writing anything.\nfunction resolveImageRestore(args: Record<string, unknown>, ctx: ProxyToolCtx): ProxyToolResult {\n    const index = ctx.session.incomingImageIndex;\n    const raw = typeof args.imageRef === \"string\" ? args.imageRef.trim() : \"\";\n    if (raw === \"\" || raw.toLowerCase() === \"list\") {\n        if (!index || index.size === 0) {\n            return toolOk(\"[No restorable images right now — this request carries no indexed historical images (the client must resend history bytes for them to be indexed).]\");\n        }\n        const lines = describeRestorable(index);\n        return toolOk(`[Restorable images (${lines.length}):]\\n${lines.join(\"\\n\")}\\nRestore one with decompress({ imageRef: \"<ref>\" }); it is written to a file you open with the read tool.`);\n    }\n    if (!index) {\n        return toolFail(`[decompress FAILED: no image history is indexed for this request — cannot restore \"${raw}\".]`);\n    }\n    const imgs = index.get(raw);\n    if (!imgs || imgs.length === 0) {\n        return toolFail(`[decompress FAILED: no restorable image for ref \"${raw}\" (it carries no image, is URL-sourced with no stored bytes, or is not in this request's history). Call decompress({ imageRef: \"list\" }) to see what is available.]`);\n    }\n    // Files were spilled at index-time, so restoring is a pure lookup: return the\n    // stored paths (verifying presence), never re-decoding or re-writing bytes.\n    const paths: string[] = [];\n    let missing = 0;\n    for (const im of imgs) {\n        if (existsSync(im.path)) paths.push(im.path);\n        else missing++;\n    }\n    if (paths.length === 0) {\n        return toolFail(`[decompress FAILED: the restored image(s) for \"${raw}\" are no longer on disk (evicted/cleaned since indexing). They will be re-spilled automatically on the next request.]`);\n    }\n    ctx.log(`[acp-image-restore] ${raw}: located ${paths.length} image(s) at ${paths.join(\", \")}${missing ? ` (${missing} missing)` : \"\"}`);\n    return toolOk(`[Restored ${paths.length} image(s) for ${raw}:\\n${paths.map((p) => `  ${p}`).join(\"\\n\")}\\nOpen them with the read tool to view the pixels.${missing ? `\\n(${missing} image(s) could not be located on disk.)` : \"\"}]`);\n}\n\n// #1294 P2: close the loop on an inline restore — kernel K2 updates the\n// inline-restored block IN PLACE when re-compressed (same id, replaced\n// summary) instead of rejecting \"already compressed\". Degrades to a generic\n// hint when the kernel could not derive exact refs (e.g. multi-segment span).\nfunction refoldHint(blockId: string, result: InlineRestoreResult | null): string {\n    if (result !== null && result.restoredStartRef && result.restoredEndRef) {\n        return `Re-fold: call compress(\"${result.restoredStartRef}–${result.restoredEndRef}\", <fresh summary>) → updates block ${blockId} in place (same id, new summary).`;\n    }\n    return `Re-fold: call compress over the restored messages with a fresh summary → updates block ${blockId} in place (same id, new summary).`;\n}\n\ntype CoveredRefs = { raws: Array<{ raw: string; num: number }>; text: string };\n\nfunction refNum(ref: string): number | null {\n    const b = parseBoundary(ref);\n    return b && b.kind === \"message\" ? b.numericId : null;\n}\n\nfunction coveredMessages(state: CompressionState, block: CompressionBlock): CoveredRefs | null {\n    const byRaw = state.messageRefs.byRaw;\n    const raws: Array<{ raw: string; num: number }> = [];\n    for (const raw of block.effectiveMessageIds) {\n        const ref = byRaw[raw];\n        if (!ref) continue;\n        const num = refNum(ref);\n        if (num === null) continue;\n        raws.push({ raw, num });\n    }\n    if (raws.length === 0) return null;\n    raws.sort((a, z) => a.num - z.num);\n    const runs: Array<[number, number]> = [];\n    for (const { num } of raws) {\n        const last = runs[runs.length - 1];\n        if (last && num === last[1] + 1) last[1] = num;\n        else runs.push([num, num]);\n    }\n    const fmtRun = ([a, z]: [number, number]) => (a === z ? `m${String(a).padStart(5, \"0\")}` : `m${String(a).padStart(5, \"0\")}–m${String(z).padStart(5, \"0\")}`);\n    const head = runs.slice(0, 5);\n    const shownCount = head.reduce((n, [a, z]) => n + (z - a + 1), 0);\n    const rest = raws.length - shownCount;\n    return { raws, text: head.map(fmtRun).join(\", \") + (rest > 0 ? ` …+${rest} more` : \"\") };\n}\n\n/** #1179 CCR v2: the message refs a block covers, as compact span text\n *  (\"m00044–m00097\") plus count — or null when no individual refs are\n *  resolvable (older blocks whose raw ids left the map). */\nexport function coveredRefSpan(state: CompressionState, block: CompressionBlock): { text: string; count: number } | null {\n    const cov = coveredMessages(state, block);\n    return cov ? { text: cov.text, count: cov.raws.length } : null;\n}\n\n// #1179 CCR v2: range-level restore — return ONLY the block's messages whose\n// refs fall within [startId, endId]. The content rides the ephemeral retrieval\n// channel: ack now, full text queued as a request-only injection (same id/role\n// shape as acp_retrieve injections, structurally excluded from fold space),\n// never cached in blockContents. Gated on CCR being armed for the session.\nfunction resolveDecompressRange(args: Record<string, unknown>, ctx: ProxyToolCtx, block: CompressionBlock): ProxyToolResult {\n    const startRaw = typeof args.startId === \"string\" ? args.startId.trim() : \"\";\n    const endRaw = typeof args.endId === \"string\" ? args.endId.trim() : \"\";\n    if (!startRaw || !endRaw) return toolFail(\"[decompress FAILED: startId and endId must be given together — pass both mNNNNN refs, or omit both to restore the whole block]\");\n    if (!ccrEnabled(ctx.session)) {\n        // Range restore needs the CCR content store; a CCR-off session has none.\n        // In plugin mode the model cannot enable CCR itself (it lives in the\n        // proxy's base config — plugin policy is the base block verbatim,\n        // #1345), so pointing it at the setting sends it chasing a config it\n        // cannot change (#1207 review F3). Give it the working call instead:\n        // whole-block restore with just blockId (#1712).\n        if (typeof ctx.session.metadata.pluginAgent === \"string\") {\n            return toolFail(`[decompress FAILED: range restore (startId/endId) requires CCR, which this plugin-mode session does not have — omit startId/endId and restore the whole block: {\"blockId\":\"${block.blockId}\"}]`);\n        }\n        return toolFail(\"[decompress FAILED: range restore (startId/endId) requires CCR — enable compress.ccr.enabled]\");\n    }\n    const sb = parseBoundary(startRaw);\n    const eb = parseBoundary(endRaw);\n    if (!sb || sb.kind !== \"message\" || !eb || eb.kind !== \"message\") {\n        return toolFail(`[decompress FAILED: startId/endId must be mNNNNN message refs (got \"${startRaw}\", \"${endRaw}\") — block ids (bN) are not valid here]`);\n    }\n    if (sb.numericId > eb.numericId) return toolFail(`[decompress FAILED: startId ${startRaw} is after endId ${endRaw} — swap them]`);\n    const state = ctx.session.state;\n    const cov = coveredMessages(state, block);\n    if (!cov) return toolFail(`[decompress FAILED: ${block.blockId} has no per-message coverage recorded (older block) — use plain decompress {blockId} for the whole block]`);\n    const pickedSet = new Set(cov.raws.filter(({ num }) => num >= sb.numericId && num <= eb.numericId).map(({ raw }) => raw));\n    if (pickedSet.size === 0) return toolFail(`[decompress FAILED: ${block.blockId} covers no messages in ${startRaw}–${endRaw} (its coverage is ${cov.text})]`);\n    const parts: string[] = [];\n    let restoredFromStore = 0;\n    // [#1283] Per-ref source selection supersedes the all-or-nothing fallback\n    // ([#1207 review F1]): store entries are immutable originals (append-only,\n    // first write wins, refs never reissued), so the store wins whenever it has\n    // the ref and the exec-time view is only the fallback (pre-CCR folds have\n    // no entries). The old zero-items gate assumed view/store mutual exclusion\n    // per ref that nothing enforces — a covered ref left visible in the view\n    // contributed its view text, which for arrival-stored refs is the 📦\n    // placeholder, not the original, and a partially visible span silently\n    // dropped the missing refs. Iterating coverage in num order keeps the span\n    // deterministic across both sources.\n    const store = contentStoreOf(ctx.session);\n    const viewById = new Map<string, CoreMessage>();\n    for (const m of ctx.compressMessages ?? ctx.messages) {\n        if (pickedSet.has(m.id)) viewById.set(m.id, m);\n    }\n    for (const { raw, num } of cov.raws) {\n        if (!pickedSet.has(raw)) continue;\n        const r = retrieveByRef(store, `m${String(num).padStart(5, \"0\")}`);\n        // #4733: a ref whose stored entry belongs to a DIFFERENT raw id is a\n        // post-restamp frozen alias — serving it here would silently restore\n        // another message's original under this one's citation. Treat as\n        // not-found and fall through to the view text.\n        if (r.ok && r.entry.rawId === raw) {\n            parts.push(r.entry.toolName ? `[${r.entry.toolName} • stored]\\n${r.text}` : `[${r.entry.kind} • stored]\\n${r.text}`);\n            restoredFromStore++;\n            continue;\n        }\n        const m = viewById.get(raw);\n        if (!m) continue;\n        parts.push(m.toolName && m.contentType !== \"text\" ? `[${m.role} • ${m.toolName}]\\n${m.text ?? \"\"}` : `[${m.role}]\\n${m.text ?? \"\"}`);\n    }\n    if (parts.length === 0) {\n        return toolFail(`[decompress FAILED: originals for ${startRaw}–${endRaw} are neither in this request's view nor in the content store (pre-CCR fold) — whole-block decompress may still work from cache]`);\n    }\n    const header = `[Block ${block.blockId} content — ${startRaw}–${endRaw} — ${parts.length} item(s)]`;\n    let injText: string;\n    const body = parts.join(\"\\n\\n\");\n    const toFileOut = toFilePointer(args, ctx, header, body);\n    if (toFileOut !== null) {\n        // #2204: a refused or unwritable export is a hard failure — return the\n        // receipt directly. Nothing reached the channel, so no injection is\n        // queued and no restore is counted; the block stays untouched.\n        if (toFileOut.outcome === \"failure\") return toFileOut;\n        injText = toFileOut.text;\n    } else if (body.length > 10000) {\n        const safeBlockId = block.blockId.replace(/[^a-zA-Z0-9_-]/g, \"-\");\n        // [#1207 review F4] Span in the filename (two spans of one block in the\n        // same millisecond must not clobber each other) and 0600 (folded\n        // conversation content is not world-readable on multi-user hosts).\n        const outPath = join(tmpdir(), `acp-decompress-${safeBlockId}-${startRaw}-${endRaw}-${Date.now()}.txt`);\n        try {\n            mkdirSync(dirname(outPath), { recursive: true });\n            writeFileSync(outPath, body, { encoding: \"utf8\", mode: 0o600 });\n            trackedTempFiles.push({ path: outPath, mtimeMs: Date.now() });\n            reapTempFiles();\n            injText = `${header}\\nContent (${body.length} chars) written to: ${outPath}\\nUse the read tool to access it.`;\n        } catch (e) {\n            return exportFailureReceipt(outPath, e, body);\n        }\n    } else {\n        injText = `${header}\\n${body}`;\n    }\n    // [#1207 review F5] A client retry re-executes this path; the injection id\n    // is deterministic, so dedupe on it — retries re-ack without queueing a\n    // duplicate full-text message or inflating rangeRestores.\n    const injId = retrievedMessageId(`range_${block.blockId}_${startRaw}-${endRaw}`);\n    if (!ctx.session.pendingRetrievals.some((p) => p.ref === injId)) {\n        ctx.session.pendingRetrievals.push({ ref: injId, tokens: 0, chars: body.length, queuedAt: Date.now(), ccr: false, injection: { id: injId, role: \"user\", contentType: \"text\", text: injText } });\n        ctx.session.stats.rangeRestores = (ctx.session.stats.rangeRestores ?? 0) + 1;\n    }\n    markDirty(ctx.session);\n    ctx.log(`[acp-decompress-range] ${block.blockId} ${startRaw}–${endRaw}: restored ${parts.length} item(s)${restoredFromStore ? ` (${restoredFromStore} from content store)` : \"\"} via ephemeral injection`);\n    return toolOk(`[decompress ${block.blockId} ${startRaw}–${endRaw}: restored ${parts.length} item(s) — full content follows]`);\n}\n\n\n\n/** Shared search_context execution for all wire paths. Distinguishes \"no active\n *  blocks at all\" (searching is pointless until compress runs — an explicit\n *  message stops premature-search retry loops, #714) from \"blocks exist but none\n *  matched\". */\n// #1333: read-only fallback for explicitly derived sessions (pi RLM child:\n// the plugin reported its parent at register and the server recorded the\n// link in metadata.derivedFromSessionId). Local miss → walk the parent chain\n// (depth cap 8, cycle-guarded), resident-or-disk. Ancestor state is never\n// mutated: no restoredInline flag, no cache write, no markDirty.\nconst DERIVED_CHAIN_MAX_DEPTH = 8;\n\nexport function derivedAncestorSessions(session: Session): Session[] {\n    const out: Session[] = [];\n    const seen = new Set<string>([session.id]);\n    let cursor: Session = session;\n    while (out.length < DERIVED_CHAIN_MAX_DEPTH) {\n        const nextId: unknown = cursor.metadata.derivedFromSessionId;\n        if (typeof nextId !== \"string\" || nextId.length === 0 || seen.has(nextId)) break;\n        seen.add(nextId);\n        const next: Session | undefined = peekSession(nextId) ?? getStore().loadSync(nextId) ?? undefined;\n        if (!next) break;\n        out.push(next);\n        cursor = next;\n    }\n    return out;\n}\n\n// ===================== #1336 planning-aware retrieval =====================\n// Policy layer over the kernel's lexical candidate surface: when enabled, the\n// full candidate pool is re-ranked against the session's current todo/task\n// state (latest protectedLatestTools snapshot in context + most recent user\n// turn) and a short steering section is appended. No store/fold/injection\n// mechanics are touched. Absent plan state or disabled ⇒ byte-identical\n// output (the stable sort degrades to the kernel's lexical order).\n\nconst EFFECTIVE_SEARCH_PLAN_KEY = \"searchPlanAware\";\n\n/** Stamp the last-resolved plan-aware flag onto the session (per-request,\n *  latest wins — same pattern as storeEffectiveCcr/storeEffectiveConfig). */\nexport function storeEffectiveSearchPlanAware(session: Session, on: boolean): void {\n    session.metadata[EFFECTIVE_SEARCH_PLAN_KEY] = on;\n}\n\nexport function effectiveSearchPlanAware(session: Session | undefined): boolean {\n    return session?.metadata[EFFECTIVE_SEARCH_PLAN_KEY] === true;\n}\n\n// Conservative built-ins for common agent task tools; user-configured\n// protectedLatestTools patterns are added on top at search time.\nconst PLANNING_TOOL_PATTERNS = [\"TodoWrite\", \"todowrite\", \"todo_list\", \"update_plan\", \"TaskCreate\", \"TaskUpdate\"];\n// Bounded scan window + per-snapshot char cap: stale todo state must not\n// dominate ranking (risk mitigation from the issue).\nconst PLAN_WINDOW_MESSAGES = 40;\nconst PLAN_TEXT_CHAR_CAP = 4000;\n// A ref retrieved this many times earns a range-restore hint in steering.\nconst REPEAT_RETRIEVE_HINT_THRESHOLD = 2;\n\nconst PLAN_STOPWORDS = new Set([\n    \"the\", \"and\", \"for\", \"with\", \"this\", \"that\", \"from\", \"have\", \"has\", \"had\",\n    \"was\", \"were\", \"are\", \"will\", \"would\", \"should\", \"could\", \"can\", \"may\",\n    \"into\", \"onto\", \"over\", \"under\", \"about\", \"after\", \"before\", \"between\",\n    \"each\", \"all\", \"any\", \"some\", \"not\", \"but\", \"then\", \"than\", \"when\",\n    \"while\", \"where\", \"which\", \"who\", \"what\", \"how\", \"why\", \"because\",\n    \"being\", \"done\", \"todo\", \"todos\", \"task\", \"tasks\", \"status\", \"pending\",\n    \"in_progress\", \"completed\", \"cancelled\", \"progress\", \"update\", \"updates\",\n    \"step\", \"steps\", \"item\", \"items\", \"list\", \"plan\",\n]);\n\ntype PlanTerms = Map<string, number>;\n\nfunction planTokenize(text: string): string[] {\n    const out: string[] = [];\n    // Rendered ref-tag markup () is proxy metadata, not plan content.\n    const clean = text.replace(/\\x3cacp\\b[\\s\\S]*?\\x3c\\/acp\\x3e/g, \" \");\n    const re = /[a-z0-9]+|[\\u4e00-\\u9fff]/g;\n    let m: RegExpExecArray | null;\n    while ((m = re.exec(clean.toLowerCase())) !== null) {\n        const t = m[0];\n        const cjk = /[\\u4e00-\\u9fff]/.test(t);\n        // Latin tokens need >= 3 chars to carry signal; CJK single chars count.\n        if (!cjk && t.length < 3) continue;\n        if (!cjk && PLAN_STOPWORDS.has(t)) continue;\n        out.push(t);\n    }\n    return out;\n}\n\nfunction resolveDerivedDecompress(\n    args: Record<string, unknown>,\n    ctx: ProxyToolCtx,\n    blockId: string,\n): ProxyToolResult {\n    for (const anc of derivedAncestorSessions(ctx.session)) {\n        const block = ctx.core.decompress(blockId, anc.state);\n        if (!block) {\n            const ancArchived = preCompactionArchiveOf(anc)[blockId];\n            if (ancArchived !== undefined) {\n                return toolFail(`[decompress FAILED: block ${blockId} is an archived block in derived session ${anc.id} (${ancArchived.reason}) — it was removed from live state along with its covered substrate and cannot be restored.]`);\n            }\n            continue;\n        }\n        if (preCompactionArchiveOf(anc)[blockId] !== undefined) {\n            return toolFail(`[decompress FAILED: block ${blockId} is a pre-compaction archive in derived session ${anc.id} — its content was replaced by the client's compaction summary and is no longer reachable.]`);\n        }\n        if (hasRangeArgs(args)) {\n            return toolFail(`[decompress FAILED: range restore (startId/endId) of derived-parent blocks is not supported — decompress \"${blockId}\" without range args (#1333)]`);\n        }\n        const full = args.full === true || args.full === \"true\";\n        const cached = anc.blockContents.get(blockId);\n        const view = cached ? (full ? cached.full : (cached.one ?? cached.full)) : undefined;\n        const body = view?.text || block.summary;\n        const count = view?.count ?? 0;\n        const header = `[Block ${blockId} content — ${count} item(s)${full ? \", full\" : \"\"} · read-only from derived session ${anc.id} (#1333)]`;\n        return toolOk(`${header}\\n${body}`);\n    }\n    return toolFail(`[Block ${blockId} not found]`);\n}\n\n/** Extract the current plan state from the in-context message view: the LAST\n *  tool call matching each planning pattern (mirrors the kernel's\n *  collectLatestProtected latest-wins semantics — per projected path for\n *  slash patterns, so `skill/*` keeps one slot per skill, #1947) plus the\n *  most recent user turn. Returns null when nothing usable is in context. */\nexport function extractPlanState(messages: CoreMessage[], extraPatterns?: string[]): { terms: PlanTerms } | null {\n    const patterns = [...new Set([...PLANNING_TOOL_PATTERNS, ...(extraPatterns ?? [])])];\n    const start = Math.max(0, messages.length - PLAN_WINDOW_MESSAGES);\n    const latestByPattern = new Map<string, CoreMessage>();\n    let lastUserText: string | undefined;\n    for (let i = start; i < messages.length; i++) {\n        const msg = messages[i];\n        if (msg.contentType === \"tool-call\" && msg.toolName) {\n            for (const p of patterns) {\n                if (matchToolMessagePattern(msg, p)) {\n                    // Slash patterns protect per projected path in the kernel;\n                    // keying by pattern would collapse every skill into one\n                    // global-latest slot (#1947).\n                    latestByPattern.set(p.includes(\"/\") ? toolPathOf(msg) : p, msg);\n                    break;\n                }\n            }\n        } else if (msg.role === \"user\" && msg.contentType === \"text\" && msg.text) {\n            lastUserText = msg.text;\n        }\n    }\n    const sources: Array<{ text: string; weight: number }> = [];\n    for (const msg of latestByPattern.values()) if (msg.text) sources.push({ text: msg.text, weight: 2 });\n    if (lastUserText) sources.push({ text: lastUserText, weight: 1 });\n    if (sources.length === 0) return null;\n    const terms: PlanTerms = new Map();\n    for (const { text, weight } of sources) {\n        const capped = text.length > PLAN_TEXT_CHAR_CAP ? text.slice(0, PLAN_TEXT_CHAR_CAP) : text;\n        for (const tok of planTokenize(capped)) {\n            terms.set(tok, (terms.get(tok) ?? 0) + weight);\n        }\n    }\n    return terms.size > 0 ? { terms } : null;\n}\n\nfunction planBlockScore(topic: string | undefined, summary: string, terms: PlanTerms): number {\n    const hay = `${topic ?? \"\"}\\n${summary}`.toLowerCase();\n    let score = 0;\n    for (const [term, w] of terms) {\n        if (!hay.includes(term)) continue;\n        let count = 0;\n        let idx = hay.indexOf(term);\n        while (idx !== -1) {\n            count++;\n            idx = hay.indexOf(term, idx + term.length);\n        }\n        score += w * count;\n    }\n    return score;\n}\n\nfunction buildSteering(\n    scored: Array<{ block: CompressionBlock; score: number }>,\n    state: CompressionState,\n    session: Session,\n): string {\n    const parts: string[] = [];\n    const boosted = scored.filter((s) => s.score > 0).slice(0, 3);\n    if (boosted.length > 0) {\n        parts.push(`top fetch targets: ${boosted.map((s) => {\n            const span = coveredRefSpan(state, s.block);\n            return span ? `${s.block.blockId} [${span.text} · ${span.count} msgs]` : s.block.blockId;\n        }).join(\", \")}`);\n    }\n    const counts = session.retrieveCountsByRef;\n    if (counts && counts.size > 0) {\n        const seen = new Set<string>();\n        const hints: string[] = [];\n        outer: for (const s of scored.slice(0, 5)) {\n            const cov = coveredMessages(state, s.block);\n            if (!cov) continue;\n            for (const { num } of cov.raws) {\n                const ref = `m${String(num).padStart(5, \"0\")}`;\n                const n = counts.get(ref);\n                if ((n ?? 0) >= REPEAT_RETRIEVE_HINT_THRESHOLD && !seen.has(ref)) {\n                    seen.add(ref);\n                    hints.push(`${ref} retrieved ${n} times this session — decompress({blockId:\"${s.block.blockId}\",startId:\"${ref}\",endId:\"${ref}\"}) may be cheaper than repeat acp_retrieve`);\n                    if (hints.length >= 2) break outer;\n                }\n            }\n        }\n        if (hints.length > 0) parts.push(hints.join(\"; \"));\n    }\n    return parts.length > 0 ? `\\n\\n[plan-aware] ${parts.join(\"\\n\")}` : \"\";\n}\n\ntype SearchPlanOpts = {\n    messages: CoreMessage[];\n    session: Session;\n    log: (msg: string) => void;\n    protectedPatterns?: string[];\n};\n\n// #2751: preview windowing. The old fixed head-clamp (safePrefix 200) hid a hit\n// whose only occurrence sat past char 200, and \"Found N\" was indistinguishable\n// from \"N is all that exists\". Center the preview on the pool-rarest matched\n// term (marking it) so unique-match evidence survives truncation; budget stays\n// at the old 200-char total so output never grows unbounded.\nconst SNIPPET_TOTAL = 200;\nconst SNIPPET_AHEAD = 80;\n\n// Code-unit-safe middle slice — never leaves a lone surrogate at an edge\n// (#816/#828/#1615: hand-sliced model-visible text must reuse this discipline).\nfunction safeMidSlice(text: string, start: number, end: number): string {\n    let s = start;\n    let e = end;\n    if (s > 0 && s < text.length) {\n        const c = text.charCodeAt(s);\n        if (c >= 0xdc00 && c <= 0xdfff) s += 1;\n    }\n    if (e > 0 && e < text.length) {\n        const c = text.charCodeAt(e - 1);\n        if (c >= 0xd800 && c <= 0xdbff) e -= 1;\n    }\n    return text.slice(s, e);\n}\n\nfunction poolTermFrequency(pool: CompressionBlock[], terms: string[]): Map<string, number> {\n    const freq = new Map<string, number>();\n    const lower = terms.map((t) => t.toLowerCase()).filter(Boolean);\n    for (const t of lower) if (!freq.has(t)) freq.set(t, 0);\n    for (const b of pool) {\n        const hay = `${b.topic ?? \"\"}\\n${b.summary}`.toLowerCase();\n        for (const t of lower) if (hay.includes(t)) freq.set(t, (freq.get(t) ?? 0) + 1);\n    }\n    return freq;\n}\n\n// Most distinctive query term present in this block's summary = fewest\n// containing blocks, tie → earliest occurrence. Null when no term is in the\n// summary body (hit then lives in the topic, already shown in the header line).\nfunction pickAnchorTerm(summary: string, terms: string[], freq: Map<string, number>): { term: string; index: number } | null {\n    const lower = summary.toLowerCase();\n    let best: { term: string; index: number; freq: number } | null = null;\n    for (const t of terms) {\n        const tl = t.toLowerCase();\n        if (!tl) continue;\n        const i = lower.indexOf(tl);\n        if (i === -1) continue;\n        const f = freq.get(tl) ?? 0;\n        if (!best || f < best.freq || (f === best.freq && i < best.index)) best = { term: tl, index: i, freq: f };\n    }\n    return best ? { term: best.term, index: best.index } : null;\n}\n\nfunction markFirstMatch(text: string, needle: string): string {\n    const idx = text.toLowerCase().indexOf(needle);\n    if (idx === -1) return text;\n    return text.slice(0, idx) + \"\\u3010\" + text.slice(idx, idx + needle.length) + \"\\u3011\" + text.slice(idx + needle.length);\n}\n\nfunction evidenceSnippet(summary: string, terms: string[], freq: Map<string, number>): string {\n    const anchor = pickAnchorTerm(summary, terms, freq);\n    if (!anchor) return summary.length > SNIPPET_TOTAL ? safePrefix(summary, SNIPPET_TOTAL) + \"...\" : summary;\n    const start = Math.max(0, anchor.index - SNIPPET_AHEAD);\n    const end = Math.min(summary.length, start + SNIPPET_TOTAL);\n    const win = markFirstMatch(safeMidSlice(summary, start, end), anchor.term);\n    return (start > 0 ? \"... \" : \"\") + win + (end < summary.length ? \" ...\" : \"\");\n}\n\n// #2751: for a long multi-term query, if a term is absent from every returned\n// block yet present in lower-ranked candidates, steer the model to narrow to it\n// rather than reading \"absent from top-N\" as \"absent from history\". At most once.\nfunction narrowingHint(terms: string[], returned: CompressionBlock[], ranked: CompressionBlock[]): string {\n    if (terms.length < 3) return \"\";\n    const returnedSet = new Set(returned);\n    const lowerCands = ranked.filter((b) => !returnedSet.has(b));\n    if (lowerCands.length === 0) return \"\";\n    const contains = (b: CompressionBlock, tl: string): boolean =>\n        (b.topic ?? \"\").toLowerCase().includes(tl) || b.summary.toLowerCase().includes(tl);\n    let best: { term: string; count: number } | null = null;\n    for (const t of terms) {\n        const tl = t.toLowerCase();\n        if (!tl) continue;\n        if (returned.some((b) => contains(b, tl))) continue;\n        const count = lowerCands.filter((b) => contains(b, tl)).length;\n        if (count === 0) continue;\n        if (!best || count < best.count || (count === best.count && t.length > best.term.length)) best = { term: t, count };\n    }\n    if (!best) return \"\";\n    return `[tip: none of the top ${returned.length} results contain \"${best.term}\" but ${best.count} lower-ranked candidate(s) do — try searching \"${best.term}\" alone to surface its block directly]`;\n}\n\n/** Folded-original-text provider: yields the full pre-fold text of every\n *  block the host still has content for (session.blockContents — resident or\n *  lazy-reloaded from the store). Used by search_context to look PAST the\n *  model-written summaries into the verbatim originals (#4154: a consumed\n *  block's content is reachable today only via decompress; search pretended\n *  it did not exist). Providers are an enhancement: failures degrade to\n *  summary-only search, never fail the tool call. */\ntype OriginalTextProvider = () => Array<{ blockId: string; text: string }>;\n\n// Strip rendered acp ref tags from folded originals before indexing: the\n// wrapper (`tokens=\"506\" type=\"text\"`) is protocol chrome, not content —\n// left in, every query containing \"token\" or \"type\" would false-positive\n// against every block. The inner message ref (mNNNNN) is kept: it is the\n// anchor the model needs to plan a range decompress.\nconst ACP_TAG_RE = /\\x3cacp\\s[^\\x3e]*\\x3e([^\\x3c]*)\\x3c\\/acp\\x3e/g;\nfunction stripAcpTags(text: string): string {\n    return text.replace(ACP_TAG_RE, \"$1\");\n}\n\nfunction originalTextsOf(session: Session): OriginalTextProvider {\n    return () => {\n        const out: Array<{ blockId: string; text: string }> = [];\n        for (const [blockId, content] of session.blockContents) {\n            const text = content?.full?.text;\n            if (typeof text === \"string\" && text.length > 0) out.push({ blockId, text: stripAcpTags(text) });\n        }\n        return out;\n    };\n}\n\nexport function executeSearchContext(\n    args: Record<string, unknown>,\n    _core: CompressionCore,\n    state: CompressionState,\n    foreignSessionId?: string,\n    plan?: SearchPlanOpts,\n    originals?: OriginalTextProvider,\n): ProxyToolResult {\n    const query = typeof args.query === \"string\" ? args.query : \"\";\n    if (query.length === 0) return toolFail(\"[search_context FAILED: query is required]\");\n    const scope = foreignSessionId ? ` in session ${foreignSessionId}` : \"\";\n    const rawLimit = typeof args.limit === \"number\" ? args.limit : typeof args.limit === \"string\" && /^\\d+$/.test(args.limit.trim()) ? Number(args.limit.trim()) : NaN;\n    const limit = Number.isFinite(rawLimit) && rawLimit > 0 ? Math.floor(rawLimit) : 5;\n    const terms = query.toLowerCase().split(/\\s+/).filter(Boolean);\n    // #4154: the pool is EVERY block (active + inactive/consumed), ranked by\n    // the kernel's public search surface (blockDocs + searchBlocks) instead\n    // of the active-only core.search wrapper. A consumed block's summary is\n    // real history the model can still act on — it must stay findable, with\n    // the render marking it inactive so decompress is the obvious next step.\n    // Algorithm = \"substring\" with a ~zero floor: the default \"hybrid\"\n    // algorithm's fuzzy n-gram component surfaces blocks for garbage queries\n    // (non-matches become weak matches), which would regress the #2751\n    // no-match answer; substring + minScore 1e-9 keeps the exact current\n    // semantics — one literal occurrence is a positive signal, never\n    // silently dropped (#2158), zero occurrences = no match.\n    const blockById = new Map(state.blocks.map((b) => [b.blockId, b]));\n    const pool = searchBlocks(blockDocs(state), query, { limit: state.blocks.length, algorithm: \"substring\", minScore: 1e-9 })\n        .map((r) => blockById.get(r.ref))\n        .filter((b): b is CompressionBlock => b !== undefined);\n    const freq = poolTermFrequency(pool, terms);\n    let ranked = pool;\n    let scored: Array<{ block: CompressionBlock; score: number }> | null = null;\n    if (plan && !foreignSessionId && pool.length > limit) {\n        const planState = extractPlanState(plan.messages, plan.protectedPatterns);\n        if (planState) {\n            const withScores = pool.map((b, i) => ({ b, i, score: planBlockScore(b.topic, b.summary, planState.terms) }));\n            withScores.sort((x, y) => y.score - x.score || x.i - y.i);\n            ranked = withScores.map((s) => s.b);\n            scored = withScores.map((s) => ({ block: s.b, score: s.score }));\n            plan.log(`[acp-search-plan] \"${query}\": ${withScores.filter((s) => s.score > 0).length}/${pool.length} candidates plan-relevant → ${scored.slice(0, limit).map((s) => `${s.block.blockId}:${s.score}`).join(\", \")}`);\n        }\n    }\n    const blocks = ranked.slice(0, limit);\n    // #4154: second corpus — the verbatim pre-fold text of every block the\n    // host still holds. Capped at `limit` extra lines; blocks already ranked\n    // via their summary are not repeated. Exceptions degrade to nothing:\n    // original-text hits are strictly additive.\n    const origHits: Array<{ r: SearchResult; spanText: string | null; count: number }> = [];\n    if (originals) {\n        try {\n            const entries = originals().filter((e) => blockById.has(e.blockId) && e.text.length > 0);\n            if (entries.length > 0) {\n                const docs = entries.map((e): SearchDoc => ({\n                    kind: \"block\",\n                    ref: `${e.blockId}!orig`,\n                    text: e.text,\n                    title: `original content of ${e.blockId}`,\n                    blockId: e.blockId,\n                    tier: blockById.get(e.blockId)?.tier ?? 1,\n                }));\n                // #4154: skip blocks whose summary already earned a line above —\n                // the original-text corpus only ADDS hits, never repeats them.\n                const already = new Set(blocks.map((b) => b.blockId));\n                for (const r of searchBlocks(docs, query, { limit: entries.length, algorithm: \"substring\", minScore: 1e-9 })) {\n                    if (!r.blockId || already.has(r.blockId)) continue;\n                    const block = blockById.get(r.blockId);\n                    if (!block) continue;\n                    const span = coveredRefSpan(state, block);\n                    origHits.push({ r, spanText: span?.text ?? null, count: span?.count ?? 0 });\n                    if (origHits.length >= limit) break;\n                }\n            }\n        } catch {\n            // originals are best-effort; never fail the search\n        }\n    }\n    if (blocks.length === 0 && origHits.length === 0) {\n        // #1875: an empty result is a valid answer to a query, not a failure.\n        if (state.blocks.length === 0) return toolOk(`[No compressed blocks exist yet${scope} — nothing to search.]`);\n        const origNote = originals ? \" + the folded original text\" : \"\";\n        return toolOk(`[No blocks matched \"${query}\" among ${state.blocks.length} block(s)${scope}. Scope = compressed topics/summaries (active + folded-away)${origNote} — NOT visible messages or other sessions; absence here ≠ never-discussed.]`);\n    }\n    const lines = blocks.map((b) => {\n        const topic = b.topic ?? \"(no topic)\";\n        const preview = evidenceSnippet(b.summary, terms, freq);\n        // #1179 CCR v2: covered message-ref span(s) — connect block space to\n        // store space so the model can target acp_retrieve / range decompress\n        // at individual messages instead of whole blocks.\n        const span = coveredRefSpan(state, b);\n        const spanNote = span ? ` [${span.text} · ${span.count} msgs]` : \"\";\n        // #4154: inactive = folded away by a later fold; still findable, and\n        // decompress is the documented way back to its full summary.\n        const inactiveNote = b.active ? \"\" : ` [inactive — folded away; decompress ${b.blockId} restores it]`;\n        return `${b.blockId} (T${b.tier}) \"${topic}\"${spanNote}${inactiveNote}\\n  ${preview}`;\n    });\n    const origLines = origHits.map(({ r, spanText, count }) =>\n        `${r.blockId} (original text, not in any summary)${spanText ? ` [${spanText}${count ? ` · ${count} msgs` : \"\"}]` : \"\"}\\n  ${r.preview}`\n    );\n    let steering = \"\";\n    if (scored && plan && !foreignSessionId && blocks.length > 0) {\n        const returned = new Set(blocks);\n        steering = buildSteering(scored.filter((s) => returned.has(s.block)), state, plan.session);\n    }\n    const truncNote = ranked.length > blocks.length\n        ? `\\n\\n[truncated: showing ${blocks.length} of ${ranked.length} candidates by relevance — pass limit:${ranked.length} to see the rest]`\n        : \"\";\n    const tip = narrowingHint(terms, blocks, ranked);\n    const tipNote = tip ? `\\n\\n${tip}` : \"\";\n    const origSection = origLines.length > 0\n        ? `\\n\\nOriginal-text hit(s) — verbatim folded content that no summary mentions; decompress the block for the full record:\\n${origLines.join(\"\\n\")}`\n        : \"\";\n    const note = foreignSessionId\n        ? `\\n\\n[Read-only search of historical session ${foreignSessionId}. Block ids are per-session namespaces — decompress acts on the current session only. For bulk content use bili export ${foreignSessionId} [--full].]`\n        : \"\";\n    const header = blocks.length === 0\n        ? `Found 0 summary block(s) for \"${query}\"${scope} — but ${origHits.length} folded original(s) match:`\n        : `Found ${blocks.length} block(s) for \"${query}\"${scope}:`;\n    return toolOk(`${header}\\n\\n${lines.join(\"\\n\\n\")}${truncNote}${steering}${tipNote}${origSection}${note}`);\n}\n\n// #841: resolve a requested session id to its compression state without\n// touching it — resident memory first (verbatim id or canonical alias), then\n// the persisted store. Never creates, reloads or marks anything dirty.\nfunction resolveForeignSessionState(id: string): CompressionState | null {\n    const resident = peekSession(id) ?? findSessionByCanonicalId(id);\n    if (resident) return resident.state;\n    return getStore().loadStateForSearch(id);\n}\n\nexport function executeSearchContextTarget(\n    args: Record<string, unknown>,\n    core: CompressionCore,\n    sessionId: string,\n    state: CompressionState,\n    ctx?: { messages: CoreMessage[]; config: Config; session: Session; log: (msg: string) => void },\n): ProxyToolResult {\n    const requested = typeof args.conversation_id === \"string\" ? args.conversation_id.trim() : \"\";\n    // #1336: plan-aware re-ranking applies to OWN-session searches only —\n    // foreign lookups stay read-only lexical (no other session's plan state).\n    const plan: SearchPlanOpts | undefined = ctx && effectiveSearchPlanAware(ctx.session)\n        ? { messages: ctx.messages, session: ctx.session, log: ctx.log, protectedPatterns: ctx.config.protectedLatestTools }\n        : undefined;\n    // #4154: wherever a Session object backs the state being searched, its\n    // blockContents (resident or lazy-reloaded from the store) feeds the\n    // folded-original-text corpus.\n    const ownOriginals = ctx ? originalTextsOf(ctx.session) : undefined;\n    // #1125: honor the param description's \"Defaults to the current conversation\" —\n    // the literal \"current\" (any case) resolves to this session, not the foreign lookup.\n    if (!requested || requested === sessionId || requested.toLowerCase() === \"current\") {\n        const local = executeSearchContext(args, core, state, undefined, plan, ownOriginals);\n        // #1333: a derived session (pi RLM child) has no blocks of its own —\n        // fall back to the recorded parent chain (read-only) instead of a\n        // bare \"nothing to search\".\n        if (local.text.startsWith(\"[No compressed blocks exist yet\") || local.text.startsWith('[No blocks matched \"')) {\n            const self2 = peekSession(sessionId);\n            if (self2) {\n                for (const anc of derivedAncestorSessions(self2)) {\n                    if (!searchBlocks(blockDocs(anc.state), String(args.query ?? \"\"), { limit: anc.state.blocks.length, algorithm: \"substring\", minScore: 1e-9 }).length) continue;\n                    return executeSearchContext(args, core, anc.state, anc.id, undefined, originalTextsOf(anc));\n                }\n            }\n        }\n        return local;\n    }\n    // A self-reference under an alias form (canonical pfa-* id) keeps plain\n    // current-session semantics — no \"historical session\" framing.\n    const self = peekSession(requested) ?? findSessionByCanonicalId(requested);\n    if (self?.id === sessionId) return executeSearchContext(args, core, state, undefined, plan, ownOriginals);\n    const resident = self ?? undefined;\n    const foreign = resolveForeignSessionState(requested);\n    if (!foreign) return toolFail(`[search_context FAILED: unknown session \"${requested}\"]`);\n    // Store-only sessions have no Session object in memory — their folded\n    // originals are not reachable here; the search degrades to summaries.\n    return executeSearchContext(args, core, foreign, requested, undefined, resident ? originalTextsOf(resident) : undefined);\n}\n"
    },
    {
      "path": "src/agent/dsh-native.ts",
      "content": "// Native dsh (deepseek-harness) cordis plugin (#941): full plugin-mode\n// compression for dsh WITHOUT a launcher — bare `dsh` with this plugin\n// installed via `bili plugin install dsh` (cordis.patch.yml entry) or\n// injected by the `bili dsh` launcher through the same --patch overlay that\n// used to carry dsh-acp.ts. Architecture mirrors pi-native.ts:\n//   1. plan: attach (BILLION_CONTEXT_ATTACH ?? BILLION_CONTEXT_PROXY — the\n//      launcher preset, or a user-supplied external proxy; #983: the preset\n//      is probed and a dead one falls back to spawn; #1130: runtime death of\n//      the shared proxy re-runs the same probe+fallback) or spawn the\n//      package's own proxy (ensureProxyRunning, ephemeral port, parent-pid\n//      watchdog = this dsh process);\n//   2. patch globalThis.fetch (native-intercept.ts) — model-API URLs are\n//      rewritten to `<proxy>/bili/<url>` in BOTH modes (attach shares\n//      #809 rewrite semantics; a loopback proxy target is never proxied,\n//      so launcher MITM envs are simply bypassed); already-routed `/bili/`\n//      URLs pass through untouched except for header stamping;\n//   3. register the proxy's tool manifest (compress/decompress/acp_status)\n//      as native dsh tools — parameters pass through verbatim (the manifest\n//      serves real JSON Schema, and ctx.tools.register projects\n//      definition.parameters as-is onto the wire);\n//   4. headersFor gates plugin mode exactly like pi.ts's\n//      before_provider_headers stamp: no x-bili-plugin headers until the\n//      tools are registered, so round 1 rides the proxy's wire mode instead\n//      of arriving tool-less. The conversation id comes from\n//      ctx.agents.currentInitiator() — dsh's AsyncLocalStorage attribution,\n//      read synchronously at request time inside the agent's driver chain;\n//   5. /acp command (absorbs dsh-acp.ts, now session-bound when an\n//      initiator is active, latest-session fallback otherwise);\n//   6. host-title channel (#2604): dsh owns its session names (the\n//      dsh-session-title service emits log-backed `session/title` events on\n//      fallback creation, LLM-generation acceptance and user rename,\n//      latest-wins). The plugin mirrors each one to the proxy's\n//      /__bili/plugin/session-name endpoint (pi.ts #2322 pattern) so the\n//      panel labels a conversation with the host name instead of the\n//      truncated first user message. Both services are optional — older\n//      hosts degrade to the pre-#2604 labelless behavior, never block boot.\n// Native auto-compaction stands down on BOTH planes: the INSTALLER/LAUNCHER\n// patch file keeps the host-plane row at auto:false, and the always-on\n// bili-compaction-gate entry (dsh-compaction-gate.ts) disables the web-profile\n// PRESET instances at load time (#3354, vendored from\n// deshark42/dsh-compaction-basic-disable — see dsh-compaction-disable.ts);\n// this module only DECLARES that the lane is owned, so a disabled or\n// kill-switched bili-native leaves the presets bootable with stock compaction\n// instead of pending on a service no one provides anymore (#3662).\n// dsh has no compaction event hook to observe a manual /compact, so its\n// boundary is left to the kernel's natural ingest diff (#395 gap, acceptable:\n// manual /compact is rare and auto mode is off).\n\nimport { AsyncLocalStorage } from \"node:async_hooks\";\nimport { readFileSync } from \"node:fs\";\nimport { homedir } from \"node:os\";\nimport path from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\nimport { logHostEvent } from \"./host-log.js\";\nimport * as pfChannel from \"./pf-channel.js\";\nimport { DSH_BUILD_CHECK, emitNewerClientBuildNote, walkUpNodeModuleVersion } from \"./client-build-note.js\";\nimport { ensureProxyRunning, LAUNCHER_DEFAULT_HOST, requestInstanceShutdown } from \"../launcher.js\";\nimport { isVersionNewer } from \"../update.js\";\nimport { VERSION } from \"../version.js\";\nimport { APIG_RESIGN_SCHEME, unresolvedRefusals } from \"../apig-resign.js\";\nimport { adminRelayEnabled, resolveResignSettings } from \"../config.js\";\nimport { decodeRequestBody } from \"../content-encoding.js\";\nimport { dshContextTabEnabled, dshContextTabLabel, limitsDecodedBytes } from \"../knobs.js\";\nimport { MIN_ASSUMED_WINDOW_TOKENS } from \"../util.js\";\nimport { markNativeHost, nativeAttachOrigin, nativeBootstrapGate, nativeProxyScriptPath, proxyEnvOrigin, singleFlight } from \"./native-bootstrap.js\";\nimport { bodyOverWindowDetail as sharedBodyOverWindowDetail, getDeclaredModelEndpoints, installNativeFetchIntercept, liveStateSlotEffect, noteRoutedOrigin, observeRoutedOrigin, routedBiliModelUrl, setDeclaredModelEndpoints, type GateVerdict, type NativeInterceptState } from \"./native-intercept.js\";\nimport { matchModelEndpoint, loadDeclaredModelEndpoints } from \"../model-endpoints.js\";\nimport { runOutsideFetchChain } from \"./fetch-chain/index.js\";\nimport { installNativeWebSocketIntercept } from \"./native-ws-intercept.js\";\nimport { asciiHeaderValue, fetchManifest, fetchProxyVersion, fetchStatus, fetchStatusLatest, forwardTool, reportAttributionHealth, reportRuntimeInfo, waitForProxyVersion, type ManifestTool } from \"./shared.js\";\nimport { createForkAdopter, sideShapedBody } from \"./fork-adopt.js\";\nimport { clearIncrementalProbe, createPrepareDirectSend, INCREMENTAL_TURN_MARKER_HEADER, INCREMENTAL_TURN_ID_HEADER, newIncrementalTurnId, noteIncrementalRejection, noteIncrementalAck, planIncrementalTurn, probeIncrementalTurns, rememberOriginalBody, sweepStale, wireMessagesLookAnthropic, type IncrementalWireMessage } from \"./incremental-client.js\";\nimport { declareDshCompactionActive, detectCompactionOverlayGap, dshCompactionGateTelemetry } from \"./dsh-compaction-disable.js\";\nimport { maskUrlForDiagnostics } from \"../log-mask.js\";\nimport { mediaBytesOfWireBody } from \"./media-bytes.js\";\nimport { conversationRecallStats, learnConversation, recallBoundaryOfMessages, recallConversation, recallHistoryFingerprints, recallLaneHasEntries, recallLaneKey } from \"./conversation-recall.js\";\nexport { sideShapedBody } from \"./fork-adopt.js\";\nexport { mediaBytesOfWireBody } from \"./media-bytes.js\";\n\nexport const name = \"bili-native\";\nexport const inject = [\"tools\", \"commands\", \"agents\"];\n\nconst RETRY_INTERVAL_MS = 10000;\n/** #2082: BILI_DSH_RETRY_INTERVAL_MS — test/ops knob to shrink the retry\n *  wall without wall-clock waits (same pattern as BILI_MODEL_INFO_RETRY_MS). */\nfunction retryIntervalMs(): number {\n    const raw = process.env.BILI_DSH_RETRY_INTERVAL_MS;\n    const parsed = raw === undefined ? Number.NaN : Number(raw);\n    return Number.isFinite(parsed) && parsed > 0 ? parsed : RETRY_INTERVAL_MS;\n}\n\n// #3380 P2: a registration-failure streak doubles the back-off per step up to\n// a hard cap — the incident retried an identical doomed failure on a flat 10s\n// wall 145 times in an hour while the user saw nothing change. The cap (not a\n// stop) keeps the loop alive for transient faults: a network blip or a slow\n// manifest must still heal without user action.\nconst REG_RETRY_MAX_MS = 5 * 60 * 1000;\n// #3380 P2: after this many consecutive failures, say it once in the user's\n// face with the recovery action — silence is how the incident stayed hidden.\nconst REG_GIVE_UP_NOTICE_STREAK = 5;\n/** #3380: capped exponential back-off for the registration-failure streak. */\nfunction regBackoffMs(failStreak: number): number {\n    const steps = Math.max(0, Math.min(failStreak - 1, 16));\n    return Math.min(retryIntervalMs() * 2 ** steps, REG_RETRY_MAX_MS);\n}\n\ntype AgentLike = {\n    session?: {\n        id?: unknown;\n        // #2381: dsh-session Session surface — the EpochHeader the NEXT request\n        // is compared against ({config:{provider,model,...}}). dsh-agent-loop\n        // writes each step's header into the session log BEFORE its fetch, so\n        // at fetch time this is exactly this request's routing. Absent on\n        // older builds (duck-typed access below degrades to the global\n        // selection).\n        requestHeader?: () => { config?: { provider?: unknown; model?: unknown } } | undefined;\n        // #2399: dsh fork children (commands.ts fork()) persist the parent\n        // SessionId + isSeeded on the child's SessionHeader; isSeeded gates the\n        // adoption (subagent children also carry parentSession but start from\n        // a fresh task context — no replay to adopt).\n        header?: { parentSession?: unknown; isSeeded?: unknown } | undefined;\n    } | undefined;\n};\n// #1677: DSH's command executor hands the invoking agent to the handler via the\n// invocation object ({ commandId, agent, rawInput, attachments, signal }) — but it\n// does NOT establish the AsyncLocalStorage boundary that currentInitiator() reads,\n// so command-path attribution through ALS is always empty and /acp silently fell\n// back to another (most-recently-active) session's panel. The invocation is the\n// authoritative \"who ran this command\" source. Every field is optional because older\n// dsh builds may omit them and the handlers must degrade gracefully (see\n// invocationSidOf's fallback chain).\ntype CommandInvocation = {\n    commandId?: unknown;\n    agent?: AgentLike | undefined;\n    rawInput?: unknown;\n    attachments?: unknown;\n    signal?: AbortSignal | undefined;\n};\ntype ToolExec = { agent?: AgentLike | undefined; signal?: AbortSignal };\n\ntype ToolDefinition = {\n    name: string;\n    description?: string;\n    parameters: unknown;\n    output: { schema: unknown; render: (args: unknown, value: unknown) => Array<{ type: string; text: string }> };\n    execute: (args: Record<string, unknown>, exec: ToolExec) => Promise<unknown>;\n};\n\ntype CommandOutcome = { kind: \"success\" | \"error\"; text: string };\n\nexport type PluginContext = {\n    tools: { register: (definition: ToolDefinition) => unknown };\n    commands: { register: (command: { name: string; description: string; handler: (invocation?: CommandInvocation) => Promise<CommandOutcome> }) => unknown };\n    agents: { currentInitiator?: () => AgentLike | undefined; get?: (id: string) => AgentLike | undefined };\n    // Runtime-info sources (#955), resolved via dynamic ctx.inject when the\n    // host exposes them (both are core dsh services; optional so older dsh\n    // builds or stripped hosts keep the plugin alive without model info).\n    llm?: { resolveModelInfo?: (provider: string, model: string, signal?: AbortSignal) => Promise<{ context?: { contextWindow?: number }; defaultMaxTokens?: number } | undefined> };\n    agentDefaultModel?: { currentSelection?: () => { provider?: string; model?: string } | undefined };\n    // #1772: boot-provided profile diagnostics ({startedBundles, ...}) — lets\n    // the plugin warn when the active profile runs its compaction inside an\n    // agent preset where the bundle patch cannot reach it.\n    profileContext?: { startedBundles?: readonly string[] | undefined };\n    inject?: (deps: readonly string[], callback: (sub: PluginContext) => void) => unknown;\n    // #1809: lifecycle disposal for registrations made inside an injected\n    // callback (cordis Context.effect); optional so non-cordis hosts skip it.\n    effect?: (fn: () => void | (() => void), label?: string) => void;\n    // #1590 host event bus + #2604 session bus (dsh-session Events): one\n    // cordis ctx.on covers both shapes — webserver/index-inject gathers\n    // per-startup rows for the web index (__BILI__ global for the settings\n    // entry), while session/created and session/event feed the title channel.\n    on?: (event: string, listener: ((table: Array<{ kind: string; name?: string; value?: unknown }>) => void) | ((session: { id?: unknown }, event: { type?: unknown; data?: { title?: unknown } }) => void) | ((raw: unknown, next: () => unknown) => unknown) | ((options: { sessionId?: unknown }, next: () => AsyncIterable<unknown>) => AsyncIterable<unknown>), options?: { global?: boolean }) => void;\n    // #3354: cordis service registry — the load-time compaction-disable overlay\n    // publishes its gate service here so the preset inject entries latch on it.\n    // Optional: hosts without a registry skip the gate without breaking boot.\n    reflect?: { provide?: (name: string, value: unknown) => void } | undefined;\n    // #2604: dsh session store + title service (core services on modern\n    // builds, optional so older hosts keep the plugin alive). The folded\n    // snapshot seeds labels for sessions whose `session/title` events all\n    // predate this process (resumes); the store lookup re-labels sids with\n    // live traffic after a proxy respawn (fresh dedup key, nothing armed).\n    sessions?: { get?: (id: string) => { id?: unknown } | undefined; list?: () => Array<{ id?: unknown }> };\n    sessionTitle?: { get?: (session: unknown) => { title?: unknown } | undefined };\n    // #1809: browser HTTP carrier (web/desktop profiles only) — hosts the live\n    // /bili/origin route the settings entry polls. Optional like llm/\n    // profileContext above: TUI/headless profiles lack it.\n    webServer?: {\n        // returns the disposer (cordis WebServer.register contract)\n        register: (route: {\n            kind: \"exact\" | \"prefix\";\n            path: string;\n            handler: (req: unknown, res: { writeHead: (status: number, headers?: Record<string, string>) => void; write?: (chunk: string | Uint8Array) => boolean; end: (body?: string | Uint8Array) => void }) => void | Promise<void>;\n        }) => (() => void) | undefined;\n    };\n};\n\n/** Decides whether the native bootstrap should run in this process. */\nexport function shouldBootstrapNativeDsh(env: NodeJS.ProcessEnv): boolean {\n    return nativeBootstrapGate(env, \"BILI_NATIVE_DSH\");\n}\n\n/** Native posture (#809 precedence, opencode plan shape): kill-switches >\n *  attach (BILLION_CONTEXT_ATTACH ?? BILLION_CONTEXT_PROXY) > spawn. A preset\n *  BILLION_CONTEXT_PROXY is the `bili dsh` launcher (or a user attach):\n *  routing is already owned (proxy envs / settings overlay), so we attach —\n *  probe first (#983), stamp plugin headers, rewrite raw model URLs like\n *  spawn mode, and fall back to spawning when the attach target is dead\n *  (at startup, #983, or at runtime, #1130). */\nexport function planNativeDsh(env: NodeJS.ProcessEnv): { mode: \"off\" | \"attach\" | \"spawn\"; attachOrigin?: string } {\n    if (env.BILLION_CONTEXT_PLUGIN === \"0\" || env.BILI_NATIVE_DSH === \"0\") return { mode: \"off\" };\n    if (env.BILI_PROVIDER_REWRITES !== undefined) return { mode: \"off\" };\n    const attachOrigin = nativeAttachOrigin(env) ?? proxyEnvOrigin(env);\n    if (attachOrigin !== undefined) return { mode: \"attach\", attachOrigin };\n    return { mode: \"spawn\" };\n}\n\nconst state: NativeInterceptState = { origin: undefined, ready: Promise.resolve(undefined) };\n\n// One registration lifecycle per HOST CONTEXT. toolsReady is the ONLY gate\n// for header stamping (pi.ts discipline): stamped headers flip the proxy into\n// plugin mode, which suppresses wire tool injection — stamping before the\n// local tools exist would send a tool-less request.\n// #3380: registrations live in the host process's tool layer and die ONLY\n// with their context (the apply() re-arm below is the sole reset). Proxy\n// death merely moves the origin — the execute closures read the LIVE base\n// (#983) — so proxy-death paths must NOT clear toolsReady: doing so forced a\n// doomed re-registration that DSH rejects (\"tool X is already registered\"),\n// locked the latch false forever, and silently stripped every request of its\n// identity headers (wire mode → anonymous zero-fold ledgers → 413 on large\n// sessions).\ntype RegisterState = {\n    base: string | undefined;\n    toolsReady: boolean;\n    dead: boolean;\n    retryAt: number;\n    pending: Promise<void> | undefined;\n    // #3380 P2: consecutive-failure bookkeeping — capped exponential back-off\n    // (regBackoffMs) + the one-time \"restart dsh\" notice.\n    failStreak: number;\n    lastRegistrationError: string | undefined;\n    // #3380/#3562: giveUp generation — every onGiveUp bumps this. In-flight\n    // attach/recovery chains capture it at entry, so a late commit made after\n    // the owner already gave up can no longer resurrect the cleared base\n    // (a resurrected base stamps x-bili-plugin at a dead origin until the\n    // next recovery tick).\n    giveUpSeq: number;\n};\n\nconst register: RegisterState = { base: undefined, toolsReady: false, dead: false, retryAt: 0, pending: undefined, failStreak: 0, lastRegistrationError: undefined, giveUpSeq: 0 };\n\n// #3616: generation of the origin plane. Each non-off apply() (and each test\n// reset) establishes a new world; an in-flight verify/spawn flight from an\n// OLDER world must not land its writes on top of it — the healthy-attach\n// branch used to bind register.base unconditionally, so a late probe landing\n// (a slow machine mid-recovery, or a test reset that cannot cancel the chain)\n// reverted the registered origin back to a stale one and tool calls followed\n// it there.\nlet originGen = 0;\n\n// #1797: attach/recovery chains still in flight after apply() returned — a late\n// chain would clobber the shared register mid-run of whatever executes next.\nconst pendingChains = new Set<Promise<unknown>>();\n\nfunction trackChain<T>(p: Promise<T>): Promise<T> {\n    pendingChains.add(p);\n    void p.then(\n        () => { pendingChains.delete(p); },\n        () => { pendingChains.delete(p); },\n    );\n    return p;\n}\n\n// #1772: once-per-process — the web-profile compaction caveat is logged a\n// single time even though apply() may run again after context re-arming.\nlet webProfileWarned = false;\n\n// #3651: once-per-process — the non-web-profile counterpart of the above: a\n// durable trace that the #3354 load-time overlay IS registered in a profile\n// that does not bundle @deepseek-ai/dsh-web-app (the web-profile note never\n// fires there, leaving field verification blind).\nlet nonWebTraceLogged = false;\n\n// #3380: once-per-process — the idempotent-adoption convergence notice must\n// not repeat per attempt (same discipline as webProfileWarned).\n// Unverified dsh client build note (#warn): once-per-process, same channel\n// discipline.\nlet dshNewerBuildNoted = false; // #4545, once per process\nlet regAdoptLogged = false;\n\n// #4545 newer-than-tested dsh client-build note (soft, never gates). Shared\n// machinery AND per-lane identities live in client-build-note.ts — re-exported\n// here so existing importers keep working. At-or-below-cap builds stay silent:\n// known older-build break modes already have their own overlay-latch detectors\n// (#3806 boot warning + #2474 fallback); only the untested-future direction is\n// covered.\nexport { DSH_BUILD_CHECK } from \"./client-build-note.js\";\n\n/** #3962: one-line overlay-coverage suffix for the durable profile notes.\n * The bundle-patch gate rows target four factory preset ids a profile may not\n * ship (their miss is visible only in the host loader log); the #4147\n * structural transform records every entry it actually rewrote on the shared\n * globalThis channel, so the note can state real coverage instead of leaving\n * the gate rows' fate implied. Best-effort by necessity: preset configs\n * resolve lazily, so \"so far\" is the honest frame. */\nfunction gateCoverageSuffix(): string {\n    const t = dshCompactionGateTelemetry();\n    if (t === null || t.covered.length === 0) {\n        return \" Overlay coverage so far: no preset entry rewritten in this process (preset configs resolve lazily — zero at this point does not mean zero later).\";\n    }\n    const entries = t.covered.map((c) => `${c.entry}\\u00d7${c.rows}`).join(\", \");\n    return ` Overlay coverage so far: ${t.covered.length} preset ${t.covered.length === 1 ? \"entry\" : \"entries\"} rewritten (${entries}).`;\n}\n\n/** #1590/#1809: origin of the proxy as currently reachable — register.base\n *  once bound (attach synchronously, spawn after bootstrap), else the preset\n *  env origin. Shared by the index-inject row and the live /bili/origin route. */\nfunction currentOrigin(): string | undefined {\n    const envOrigin = process.env.BILLION_CONTEXT_PROXY?.trim();\n    return register.base ?? (envOrigin !== undefined && envOrigin.length > 0 ? envOrigin : undefined);\n}\n\n/** #3373: the /__bili admin relay — dsh web's remote-panel path. With\n *  `security.adminRelay` on and the proxy bound, forward browser admin calls\n *  received on dsh's web entry to the loopback proxy, so a remote browser\n *  talks same-origin through the entry it already reached dsh by. The\n *  forwarded hop is a local non-browser client (loopback source, loopback\n *  Host via fetch, no Origin header), so the admin gate (#1538) holds\n *  unchanged; when the gate is off this stays a plain 404 (fail-closed). */\nconst RELAY_REQUEST_DROP = new Set([\n    \"connection\", \"keep-alive\", \"proxy-authenticate\", \"proxy-authorization\", \"te\",\n    \"trailer\", \"transfer-encoding\", \"upgrade\",\n    // fetch re-derives these from the target; the browser's values describe\n    // the entry origin and would leak host-session state into the proxy.\n    \"host\", \"origin\", \"cookie\", \"referer\", \"content-length\", \"accept-encoding\",\n]);\nconst RELAY_RESPONSE_DROP = new Set([\"connection\", \"keep-alive\", \"transfer-encoding\", \"content-length\", \"content-encoding\"]);\nconst RELAY_MAX_BODY_BYTES = 8 * 1024 * 1024;\n\ntype RelayRes = { writeHead: (status: number, headers?: Record<string, string>) => void; write?: (chunk: string | Uint8Array) => boolean; end: (body?: string | Uint8Array) => void };\n\nasync function relayAdminRequest(req: unknown, res: RelayRes): Promise<void> {\n    const fail = (status: number, code: string): void => {\n        try {\n            res.writeHead(status, { \"content-type\": \"application/json\" });\n            res.end(JSON.stringify({ error: code }));\n        } catch {\n            // socket already gone — nothing left to report\n        }\n    };\n    // Fail-closed presentation first: while the gate is off the route answers\n    // 404 regardless of proxy state (no state disclosure).\n    if (!adminRelayEnabled()) {\n        fail(404, \"admin relay disabled\");\n        return;\n    }\n    const base = register.base;\n    if (base === undefined) {\n        fail(503, \"bili proxy not running\");\n        return;\n    }\n    const rawMethod = (req as { method?: unknown }).method;\n    const method = typeof rawMethod === \"string\" ? rawMethod : \"GET\";\n    const rawUrl = (req as { url?: unknown }).url;\n    const url = typeof rawUrl === \"string\" ? rawUrl : \"/\";\n    // Contain the relay to the declared /__bili surface: fetch() normalizes\n    // dot segments (literal and %2e-encoded alike), so an unchecked\n    // \"/__bili/..\" would land on sibling paths of the loopback proxy.\n    const cut = url.search(/[?#]/);\n    const pathPart = cut === -1 ? url : url.slice(0, cut);\n    let decodedPath: string;\n    try {\n        decodedPath = decodeURIComponent(pathPart).replaceAll(\"\\\\\", \"/\");\n    } catch {\n        fail(400, \"bad request path\");\n        return;\n    }\n    if (decodedPath.split(\"/\").includes(\"..\")) {\n        fail(400, \"bad request path\");\n        return;\n    }\n    const headersIn = (req as { headers?: unknown }).headers;\n    const headers: Record<string, string> = {};\n    if (headersIn !== null && typeof headersIn === \"object\") {\n        for (const [key, value] of Object.entries(headersIn as Record<string, unknown>)) {\n            if (RELAY_REQUEST_DROP.has(key)) continue;\n            if (typeof value === \"string\") headers[key] = value;\n            else if (Array.isArray(value)) headers[key] = value.filter((entry): entry is string => typeof entry === \"string\").join(\", \");\n        }\n    }\n    let body: Uint8Array | undefined;\n    if (method !== \"GET\" && method !== \"HEAD\") {\n        const chunks: Buffer[] = [];\n        let size = 0;\n        try {\n            for await (const chunk of req as AsyncIterable<unknown>) {\n                const buf = typeof chunk === \"string\" ? Buffer.from(chunk) : chunk instanceof Uint8Array ? Buffer.from(chunk.buffer, chunk.byteOffset, chunk.byteLength) : undefined;\n                if (buf === undefined) break;\n                size += buf.length;\n                if (size > RELAY_MAX_BODY_BYTES) {\n                    fail(413, \"request body too large\");\n                    return;\n                }\n                chunks.push(buf);\n            }\n            body = chunks.length > 0 ? Buffer.concat(chunks) : undefined;\n        } catch {\n            fail(400, \"request body read failed\");\n            return;\n        }\n    }\n    let upstream: Response;\n    try {\n        upstream = await fetch(`${base}${url}`, {\n            method,\n            headers,\n            body,\n            redirect: \"manual\",\n            signal: AbortSignal.timeout(120_000),\n        });\n    } catch {\n        fail(502, \"bili proxy unreachable\");\n        return;\n    }\n    const headersOut: Record<string, string> = {};\n    upstream.headers.forEach((value, key) => {\n        if (!RELAY_RESPONSE_DROP.has(key)) headersOut[key] = value;\n    });\n    try {\n        res.writeHead(upstream.status, headersOut);\n        if (upstream.body !== null) {\n            if (typeof res.write === \"function\") {\n                for await (const chunk of upstream.body) res.write(chunk);\n                res.end();\n            } else {\n                res.end(Buffer.from(await upstream.arrayBuffer()));\n            }\n        } else {\n            res.end();\n        }\n    } catch {\n        // client hung up mid-stream — the upstream read dies with it\n    }\n}\n\n// #2604: host-title channel (mirror of pi.ts #2322/#2354): dsh owns its\n// session names; the proxy web UI labels a conversation from meta.hostTitle\n// when present. Pushes are fire-and-forget, deduped per (base, sid) — a\n// failed POST re-arms via map deletion, and keying on base means a\n// respawned/rebound proxy re-learns every title on next traffic or event\n// instead of trusting a dead origin's memory.\nconst lastReportedTitles = new Map<string, string>();\ntype DshSessionLike = { id?: unknown };\nconst titleServices: { sessions?: PluginContext[\"sessions\"]; sessionTitle?: PluginContext[\"sessionTitle\"] } = {};\n\nfunction reportDshSessionName(base: string | undefined, sid: string | undefined, name: string): void {\n    if (base === undefined || typeof sid !== \"string\" || sid.length === 0) return;\n    const key = `${base}\\u0000${sid}`;\n    const prev = lastReportedTitles.get(key);\n    if (prev === name || (name === \"\" && prev === undefined)) return;\n    lastReportedTitles.set(key, name);\n    fetch(`${base}/__bili/plugin/session-name`, {\n        method: \"POST\",\n        headers: { \"content-type\": \"application/json\" },\n        body: JSON.stringify({ conversationId: sid, name }),\n        signal: AbortSignal.timeout(5000),\n    }).then((res) => {\n        if (!res.ok) lastReportedTitles.delete(key);\n    }).catch(() => {\n        lastReportedTitles.delete(key);\n    });\n}\n\nfunction seedDshSessionTitle(session: DshSessionLike): void {\n    const sid = typeof session.id === \"string\" ? session.id : undefined;\n    const get = titleServices.sessionTitle?.get;\n    if (sid === undefined || typeof get !== \"function\") return;\n    let title: unknown;\n    try {\n        title = get.call(titleServices.sessionTitle, session)?.title;\n    } catch {\n        return;\n    }\n    if (typeof title === \"string\" && title.length > 0) reportDshSessionName(register.base, sid, title);\n}\n\n// Lazy re-label for a sid with live traffic but no reported title yet: covers\n// resumed sessions whose title predates this process and proxies that replaced\n// a dead one since the last event (fresh base = fresh dedup key, nothing armed).\nfunction ensureDshTitleReported(sid: string): void {\n    const base = register.base;\n    if (base === undefined || lastReportedTitles.has(`${base}\\u0000${sid}`)) return;\n    const lookup = titleServices.sessions?.get;\n    if (typeof lookup !== \"function\") return;\n    let session: DshSessionLike | undefined;\n    try {\n        session = lookup.call(titleServices.sessions, sid);\n    } catch {\n        return;\n    }\n    if (session !== undefined) seedDshSessionTitle(session);\n}\n\nfunction sweepLiveDshTitles(): void {\n    const list = titleServices.sessions?.list;\n    if (typeof list !== \"function\") return;\n    let sessions: Array<DshSessionLike>;\n    try {\n        sessions = list.call(titleServices.sessions);\n    } catch {\n        return;\n    }\n    for (const session of sessions) seedDshSessionTitle(session);\n}\n\n// Runtime-info cache (#955, rekeyed per model in #2381): one entry per\n// (provider, model) the host actually routes — what ctx.llm resolved for it\n// (contextWindow / defaultMaxTokens). Written by async refreshes; read\n// synchronously by headersFor on every model request. The pre-#2381 single\n// slot tracked the GLOBAL agent default selection while headersFor ran under\n// a SESSION initiator: a session on another model stamped the default model's\n// name, the proxy's exact-match gate discarded the whole header channel, and\n// the window fell to the unconfigured fallback. Per key, an entry can only\n// ever hold its own key's numbers, so a foreign model's window can never land\n// on another model's request.\ntype ModelInfoEntry = { provider: string; model: string; contextWindow?: number; maxOutput?: number };\nconst MODEL_INFO_CACHE_CAP = 32;\n// #1812: retry cadence for window resolves that failed (or resolved without a\n// window). The pre-#1812 code cached {provider, model} on failure and the\n// early-return below then NEVER re-resolved — one boot-time race (catalog\n// still loading) silently stripped x-bili-plugin-context-window from every\n// request of the whole process lifetime, and the proxy sized the session\n// against its unconfigured fallback. A failed resolve now retries after this\n// cooldown instead of latching.\nconst MODEL_INFO_RETRY_COOLDOWN_MS = 30_000;\nfunction modelInfoRetryCooldownMs(): number {\n    // BILI_MODEL_INFO_RETRY_MS: test hook to exercise the retry cadence without wall-clock waits.\n    const raw = process.env.BILI_MODEL_INFO_RETRY_MS;\n    const parsed = raw === undefined ? Number.NaN : Number(raw);\n    return Number.isFinite(parsed) && parsed >= 0 ? parsed : MODEL_INFO_RETRY_COOLDOWN_MS;\n}\nconst modelInfo: {\n    byKey: Map<string, ModelInfoEntry>;\n    refreshingKeys: Set<string>;\n    retryAtByKey: Map<string, number>;\n    services?: { llm?: PluginContext[\"llm\"]; agentDefaultModel?: PluginContext[\"agentDefaultModel\"] };\n} = { byKey: new Map(), refreshingKeys: new Set(), retryAtByKey: new Map() };\n\nfunction modelInfoKey(provider: string, model: string): string {\n    return `${provider}\\u0000${model}`;\n}\n\nfunction evictModelInfoEntries(): void {\n    while (modelInfo.byKey.size > MODEL_INFO_CACHE_CAP) {\n        const oldest = modelInfo.byKey.keys().next().value;\n        if (oldest === undefined) break;\n        modelInfo.byKey.delete(oldest);\n        modelInfo.retryAtByKey.delete(oldest);\n    }\n}\n\nfunction normalizeModelTarget(provider: unknown, model: unknown): { provider: string; model: string } | undefined {\n    if (typeof provider === \"string\" && provider.length > 0 && typeof model === \"string\" && model.length > 0) {\n        return { provider, model };\n    }\n    return undefined;\n}\n\n// #2381: the model THIS request routes to — the session's own live header\n// first (exact at fetch time, correct across per-session model switches), the\n// host's global default selection only as fallback. Any miss degrades to\n// pre-#2381 behavior; it never yields a wrong model.\nfunction sessionModelTargetOf(ctx: PluginContext): { provider: string; model: string } | undefined {\n    try {\n        const init = ctx.agents?.currentInitiator?.();\n        const header = init?.session?.requestHeader?.();\n        return normalizeModelTarget(header?.config?.provider, header?.config?.model);\n    } catch {\n        return undefined;\n    }\n}\n\nfunction globalModelTarget(svc: { agentDefaultModel?: PluginContext[\"agentDefaultModel\"] } | undefined): { provider: string; model: string } | undefined {\n    try {\n        const sel = svc?.agentDefaultModel?.currentSelection?.();\n        return normalizeModelTarget(sel?.provider, sel?.model);\n    } catch {\n        return undefined;\n    }\n}\n\n// #2924: the context window the gate's oversize arm compares against — the\n// SAME resolution headersFor stamps (#2381: the session's live model first,\n// the host's global default as fallback, cached model info only). A miss\n// anywhere disables the size arm; it must never yield a wrong model's window.\nfunction effectiveContextWindow(ctx: PluginContext): number | undefined {\n    const target = sessionModelTargetOf(ctx) ?? globalModelTarget(modelInfo.services);\n    if (target === undefined) return undefined;\n    return modelInfo.byKey.get(modelInfoKey(target.provider, target.model))?.contextWindow;\n}\n\n// Gate face of the shared doom math (#4111/#4516): keeps the gate's\n// init-body signature for its call sites and tests, decoding init.body into\n// the raw string the shared form (native-intercept.ts) prices with the\n// media-aware walk (media-bytes.ts).\nfunction rawBodyStringOf(init: RequestInit | undefined): string | undefined {\n    const body: unknown = init?.body;\n    if (typeof body === \"string\") return body;\n    if (body instanceof Uint8Array || body instanceof ArrayBuffer) {\n        try {\n            return new TextDecoder().decode(body instanceof Uint8Array ? body : new Uint8Array(body));\n        } catch {\n            // #4912: undecodable buffer (>V8-max-string-length throws\n            // RangeError) → undefined; sharedBodyOverWindowDetail then\n            // bills ALL bytes as core text (media=0) — the conservative\n            // refusal direction, same convention as no-init call sites.\n            return undefined;\n        }\n    }\n    return undefined;\n}\n\nexport function bodyOverWindowDetail(\n    body: { bytes: number } | undefined,\n    init: RequestInit | undefined,\n    declaredWindow: number | undefined,\n): ReturnType<typeof sharedBodyOverWindowDetail> {\n    return sharedBodyOverWindowDetail(body?.bytes, rawBodyStringOf(init), declaredWindow);\n}\n\nfunction refreshModelInfo(origin: string | undefined, target?: { provider: string; model: string }): void {\n    const svc = modelInfo.services;\n    if (svc === undefined) return;\n    const sel = target ?? globalModelTarget(svc);\n    if (sel === undefined) return;\n    const provider = sel.provider;\n    const model = sel.model;\n    const key = modelInfoKey(provider, model);\n    // #1812: a cached entry is final only when it actually carries a\n    // window (or the service has no resolver at all). A failure-shaped cache\n    // ({provider, model}, no contextWindow) retries after the cooldown.\n    const cached = modelInfo.byKey.get(key);\n    if (cached !== undefined && cached.contextWindow !== undefined) return;\n    const retryAt = modelInfo.retryAtByKey.get(key);\n    if (cached !== undefined && retryAt !== undefined && Date.now() < retryAt) return;\n    if (modelInfo.refreshingKeys.has(key)) return;\n    // The host registers llm as a service object, so resolveModelInfo needs its\n    // receiver; called detached below, this threw\n    // \"Cannot read properties of undefined (reading 'resolveModelInfoFor')\"\n    // for every provider and model, and the failure-shaped cache (#1812) then\n    // left the process without x-bili-plugin-context-window.\n    const resolve = svc.llm?.resolveModelInfo?.bind(svc.llm);\n    if (resolve === undefined) {\n        modelInfo.byKey.set(key, { provider, model });\n        evictModelInfoEntries();\n        return;\n    }\n    modelInfo.refreshingKeys.add(key);\n    modelInfo.retryAtByKey.set(key, Date.now() + modelInfoRetryCooldownMs());\n    void Promise.resolve()\n        .then(() => resolve(provider, model))\n        .then((info) => {\n            // Per-key commit (#2381): the entry belongs to its OWN key, so a\n            // model switch mid-resolve can no longer strand or clobber it —\n            // stamping reads only the live request's key, and a switched-away\n            // model's numbers stay parked under their own key (#956's\n            // user-visible contract, now structural instead of guarded).\n            modelInfo.byKey.set(key, {\n                provider,\n                model,\n                contextWindow: typeof info?.context?.contextWindow === \"number\" && info.context.contextWindow > 0 ? Math.floor(info.context.contextWindow) : undefined,\n                // #2904: forwarded verbatim from the host's defaultMaxTokens — bili never\n                // guesses. An undeclared custom model yields undefined here, emptying the\n                // ceiling chain (poisoned high-water, max-tokens truncation); fix home is\n                // DSH-side (report its configured default). See docs/technical-notes.md.\n                maxOutput: typeof info?.defaultMaxTokens === \"number\" && info.defaultMaxTokens > 0 ? Math.floor(info.defaultMaxTokens) : undefined,\n            });\n            evictModelInfoEntries();\n            if (modelInfo.byKey.get(key)?.contextWindow !== undefined) modelInfo.retryAtByKey.delete(key);\n        })\n        .catch(() => {\n            // Resolution failed (transient catalog read, model offline): keep\n            // the model id (usable for registry lookup) without window claims.\n            modelInfo.byKey.set(key, { provider, model });\n            evictModelInfoEntries();\n        })\n        .finally(() => {\n            modelInfo.refreshingKeys.delete(key);\n            const entry = modelInfo.byKey.get(key);\n            if (entry !== undefined && origin !== undefined) {\n                void reportRuntimeInfo(origin, {\n                    agent: \"dsh\",\n                    model: entry.model,\n                    contextWindow: entry.contextWindow,\n                    maxOutput: entry.maxOutput,\n                    source: \"client-config\",\n                }).catch(() => {});\n            }\n        });\n}\n\nfunction errMessage(err: unknown): string {\n    return err instanceof Error ? err.message : String(err);\n}\n\n// #1158/#2831: GUI hosts swallow process stderr, so a bootstrap failure that\n// only console.errors vanishes together with the symptom it causes (silent\n// direct-send degradation — zero interception, zero trace). Append the fact\n// to the shared bili.log in the proxy's own line shape, origin-marked\n// [dsh-client]. Best-effort semantics, line grammar and rotation safety live\n// in host-log.ts (#2827).\nexport function persistClientEvent(msg: string): void {\n    logHostEvent(\"warn\", \"[dsh-client]\", msg);\n}\n\nasync function bootstrap(): Promise<string | undefined> {\n    // #3616: superseded flights must not bind the newer world's origin plane.\n    const gen = originGen;\n    try {\n        const handle = await ensureProxyRunning(\n            { host: LAUNCHER_DEFAULT_HOST, port: 0, passthrough: false, debug: false, lane: \"dsh\" },\n            { scriptPath: nativeProxyScriptPath() },\n        );\n        if (gen !== originGen) return handle.origin;\n        state.origin = handle.origin;\n        register.base = handle.origin;\n        // #983: do NOT write BILLION_CONTEXT_PROXY — dsh has no reader 